INSERT OR IGNORE INTO quiz_questions(id,quiz_id,prompt,options_json,correct_index,position) VALUES
(101,1,'پیش از انتشار یک خبر مهم، بهترین اقدام چیست؟','["بررسی منبع و تاریخ و مقایسه با منابع معتبر","ارسال سریع به دیگران","تکیه بر تعداد بازدیدها","اعتماد به تصویر بدون بررسی"]',0,1),
(102,1,'کدام مورد نشانه کافی برای درست بودن یک ادعا نیست؟','["وجود سند قابل بررسی","ارجاع به منبع اولیه","تعداد زیاد بازنشر","تأیید مستقل از چند منبع"]',2,2),
(103,1,'اگر تاریخ یک تصویر مشخص نباشد، چه باید کرد؟','["تاریخ و منشأ آن را جست‌وجو کرد","آن را قطعاً مربوط به امروز دانست","توضیح دلخواه نوشت","بدون بررسی منتشر کرد"]',0,3),
(104,1,'در یک گزارش آماری، کدام موضوع مهم است؟','["روش گردآوری و حجم نمونه","فقط رنگ نمودار","صرفاً تعداد لایک","نام فایل"]',0,4),
(105,1,'هنگام پیدا کردن اشتباه در محتوای منتشرشده، رفتار درست چیست؟','["اصلاح شفاف و اطلاع‌رسانی درباره تغییر","پاک‌کردن بدون توضیح","تکرار اشتباه","سرزنش مخاطب"]',0,5),
(201,2,'برای بررسی‌پذیری یک گزارش عملکرد چه چیزی ضروری است؟','["هدف روشن و شاخص قابل اندازه‌گیری","شعار بدون داده","عکس‌های پرشمار","حذف روش اندازه‌گیری"]',0,1),
(202,2,'تعارض منافع احتمالی را چگونه باید مدیریت کرد؟','["افشا و پیروی از سازوکار قانونی رسیدگی","نادیده گرفتن آن","پنهان‌کردن موضوع","واگذاری تصمیم به شایعه"]',0,2),
(203,2,'کدام روش برای رسیدگی به شکایت مناسب‌تر است؟','["فرایند ثبت و پاسخ‌گویی قابل پیگیری","حذف شکایات منفی","پاسخ ندادن","رسیدگی فقط به آشنایان"]',0,3),
(204,2,'گزارش هزینه‌ها چگونه قابل اتکاتر می‌شود؟','["ثبت مستندات و امکان حسابرسی","ثبت مبالغ تقریبی بدون سند","انتشار ناقص","حذف هزینه‌های خرد"]',0,4),
(205,2,'هنگام استفاده از داده‌های اشخاص چه اصل مهم است؟','["رضایت آگاهانه و محدودکردن جمع‌آوری داده","جمع‌آوری بدون هدف","اشتراک‌گذاری عمومی اطلاعات","نگهداری نامحدود همه داده‌ها"]',0,5);
